def number_and_reinstate_floors(apps, schema_editor):
    """Give each existing plan a floor number, and put every plan back in service.

    Before this migration only one plan could be active, and switching to a
    newly drawn upper floor deactivated the ground floor -- taking every book
    on it out of the catalogue, because a book is only locatable while its
    floor plan is active. Any plan deactivated by that old rule is therefore
    reinstated here rather than left switched off, and the plans are numbered
    in the order they were created so the ground floor comes first.
    """
    FloorPlan = apps.get_model('library', 'FloorPlan')
    for i, plan in enumerate(FloorPlan.objects.order_by('floor_plan_id'), start=1):
        plan.floor_number = i
        plan.is_active = True
        plan.save(update_fields=['floor_number', 'is_active'])


